// Google Tasks -> Ziffr: which tasks with a Ziffr ref were ticked or un-ticked since we last told Ziffr, and which got a "Reply:" line.
const SYSTEM = 'google-tasks';
const LIMIT = 100;
const ID = /^[A-Za-z0-9_=-]{1,100}$/;
const TASKS = (res) => (res.items || []).map((t) => ({ id: t.id, title: t.title, done: t.status === 'completed', notes: t.notes || '', url: t.webViewLink }));
const TASK = (t) => ({ id: t.id, url: t.webViewLink });
const DUE = (due) => (due ? due + 'T00:00:00.000Z' : null);
const STATE = (open) => (open ? 'needsAction' : 'completed');
const createBody = (title, notes, due, open) => { const b = { title, notes, status: STATE(open) }; if (due) b.due = DUE(due); return b; };
const patchBody = (title, due, open) => (open ? { title, due: DUE(due), status: STATE(true), completed: null } : { title, due: DUE(due), status: STATE(false) });
const closeBody = () => ({ status: 'completed' });
const state = $getWorkflowStaticData('global');
state.reported = state.reported || {};
state.replied = state.replied || {};
const tasks = TASKS($input.first().json);
const out = [];
const present = new Set();
for (const t of tasks) {
  // Ziffr's block is the first lines up to the LAST whole line that is the marker; its first line holds the ref.
  const lines = t.notes.split(/\r?\n/);
  let end = -1;
  lines.forEach((l, i) => { if (/^--- end of Ziffr text ---[ \t]*$/.test(l)) end = i; });
  const m = end < 0 ? null : /^Ziffr ref: ([A-Za-z0-9]+-\d+)[ \t]*$/.exec(lines[0]);
  if (!m) continue;
  const ref = m[1];
  present.add(ref);
  const was = state.reported[ref];
  if (t.done && was !== 'done') out.push({ json: { ref, ziffr: { op: 'done', system: SYSTEM, external_id: t.id } } });
  else if (!t.done && was === 'done') out.push({ json: { ref, ziffr: { op: 'reopen', system: SYSTEM, external_id: t.id } } });
  const reply = lines.slice(end + 1).map((l) => /^Reply:[ \t]*(.+)$/.exec(l)).find((x) => x);
  const text = reply ? Array.from(reply[1].trim()).slice(0, 1000).join('') : '';
  if (text && state.replied[ref] !== text) out.push({ json: { ref, ziffr: { op: 'reply', system: SYSTEM, external_id: t.id, text } } });
}
// Forget what is no longer in a list we saw whole; Ziffr allows 60 requests a minute, so a run sends at most 30.
const whole = tasks.length < LIMIT;
if (whole) for (const k of Object.keys(state.reported)) if (!present.has(k)) delete state.reported[k];
if (whole) for (const k of Object.keys(state.replied)) if (!present.has(k)) delete state.replied[k];
return out.slice(0, 30);

// Signs the request exactly as Ziffr signs its messages: HMAC-SHA256 of "<timestamp>.<raw body>" with the Webhook's secret.
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on a self-hosted n8n.
const crypto = require('crypto');
const cfg = $('Settings').first().json;
const base = String(cfg.ziffrUrl).replace(/\/+$/, '');
return $input.all().map((item) => {
  const body = JSON.stringify(item.json.ziffr);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'sha256=' + crypto.createHmac('sha256', cfg.secret).update(timestamp + '.' + body).digest('hex');
  return { json: { url: base + '/api/webhooks/' + encodeURIComponent(cfg.webhookId) + '/in', body, timestamp, signature, op: item.json.ziffr.op, ref: item.json.ref || item.json.ziffr.ref, text: item.json.ziffr.text } };
});

// Writes down what Ziffr took (200: done; 409: Ziffr's rules say no, asking again would not help), so it is not sent twice.
const state = $getWorkflowStaticData('global');
state.reported = state.reported || {};
state.replied = state.replied || {};
const sent = $('Sign request').all();
let handled = 0;
$input.all().forEach((res, i) => {
  const s = sent[i] && sent[i].json;
  const code = res.json.statusCode;
  if (!s || (code !== 200 && code !== 409)) return;
  handled++;
  if (s.op === 'done') state.reported[s.ref] = 'done';
  if (s.op === 'reopen') state.reported[s.ref] = 'open';
  if (s.op === 'reply') state.replied[s.ref] = s.text;
});
return [{ json: { handled } }];
